item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported result cannot establish variation across repeated runs."
        }
      ],
      "instrument_review": "MESA 14 and 16: repeated testing and score stability remain unestablished; missing information is not evidence that testing did not occur."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "A single run supplies no evidence of stability or instability across runs."
        }
      ],
      "instrument_review": "MESA 14: repeated testing explicitly did not occur. MESA 16: stability remains unknown; absence of testing does not demonstrate unstable scores."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under the same conditions explicitly occurred."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 and 16: repeated testing measured variation, and the observed range supports stability under the stated criterion and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing occurred regardless of whether its results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: repeated testing occurred. MESA 16: the measured variation contradicts stability under the stated criterion; testing and favourable findings are separate issues."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about variation across runs."
        }
      ],
      "instrument_review": "MESA 22: installation instructions help describe setup. They do not resolve the missing repeated-testing and variation evidence relevant to MESA 14 and 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 13, 20 and 25: the observed comparison supports the narrow intended use. Broader performance claims lack evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended use involving general intelligence does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "MESA 9, 20 and 25: the grid results support the narrow comparison, but coverage and evidence beyond the test are insufficient for the stated general-intelligence selection use."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved real workshop decisions; the later trial cannot supply evidence available initially."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop, with a reported difference interval of 12 to 28 percentage points."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA 16, 20 and 25: the later randomized trial and uncertainty interval support the intended workshop correctness comparison. Initial scores alone and the unmeasured safety outcome do not support the broader claims."
    }
  ],
  "closing_note": "No instructions required clarification. Probe labels classify evidential support, not MESA ratings; missing evidence was distinguished from explicit contradiction."
}
